### 2. Complete xv6-riscv Source Code (Modified & New Files)

#### A. Kernel Changes (`kernel/sysfile.c` snippet)
```c
// Add to kernel/sysfile.c
#include "fs.h"
#include "buf.h"

uint64 sys_get_dinode(void) {
  int inum;
  uint64 addr; 
  struct buf *bp;
  struct dinode *dip;
  struct superblock sb;

  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0)
    return -1;

  readsb(1, &sb); // Read superblock to use IBLOCK macro
  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);

  struct inode_info info;
  info.type = dip->type;
  info.nlink = dip->nlink;
  info.size = dip->size;
  memmove(info.addrs, dip->addrs, sizeof(info.addrs));

  brelse(bp);
  if(copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info)) < 0)
    return -1;
  return 0;
}
```

