#### C. External Recovery Tool (`recovery.py`)
```python
import struct, os, sys

BSIZE = 1024
IPB = BSIZE // 64
ROOTINO = 1

class XV6RecoveryTool:
    def __init__(self, img="fs.img"):
        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes, self.inodestart = sb[3], sb[6]

    def get_inode(self, inum):
        self.f.seek((self.inodestart * BSIZE) + (inum * 64))
        r = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": r[0], "size": r[4], "addrs": list(r[5:])}

    def repair(self):
        allocated = [i for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0]
        reachable = set()
        def walk(inum):
            if inum in reachable or inum == 0: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1: # Directory
                for addr in ino['addrs'][:12]:
                    if addr == 0: continue
                    self.f.seek(addr * BSIZE)
                    for _ in range(BSIZE // 16):
                        de = struct.unpack("<H14s", self.f.read(16))
                        if de[0] > 0 and de[1].split(b'\0')[0] not in [b'.', b'..']:
                            walk(de[0])
        walk(ROOTINO)
        orphans = set(allocated) - reachable
        print(f"Orphaned Inodes Found: {orphans}" if orphans else "FS Healthy")

if __name__ == "__main__":
    tool = XV6RecoveryTool()
    tool.repair()
```

