### 2. Missing Source Code: `user/directoryWalker.c`

This C program traverses the xv6 directory tree to identify all reachable files and their associated inodes.

```c
#include "kernel/types.h"
#include "kernel/stat.h"
#include "user/user.h"
#include "kernel/fs.h"

void directoryWalker(char *path) {
  int fd;
  struct dirent de;
  struct stat st;
  char buf[512], *p;

  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0) { close(fd); return; }

  if(st.type == T_DIR) {
    strcpy(buf, path);
    p = buf + strlen(buf);
    if(*(p-1) != '/') *p++ = '/';

    while(read(fd, &de, sizeof(de)) == sizeof(de)) {
      if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0) continue;
      memmove(p, de.name, DIRSIZ);
      p[DIRSIZ] = 0;
      struct stat st_inner;
      if(stat(buf, &st_inner) == 0) {
        printf("Path: %-25s | Inode: %-4d | Type: %d\n", buf, st_inner.ino, st_inner.type);
        if(st_inner.type == T_DIR) directoryWalker(buf);
      }
    }
  } else {
    printf("Path: %-25s | Inode: %-4d | Type: %d\n", path, st.ino, st.type);
  }
  close(fd);
}

int main(int argc, char *argv[]) {
  directoryWalker(argc < 2 ? "/" : argv[1]);
  exit(0);
}
```

