### 3. Final Recovery Suite (Python)

```python
import struct, sys, os

BSIZE = 1024
ROOTINO = 1

class XV6RecoverySuite:
    def __init__(self, image_path):
        self.f = open(image_path, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes, self.inodestart = sb[3], sb[6]

    def get_inode(self, inum):
        self.f.seek((self.inodestart * BSIZE) + (inum * 64))
        res = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"inum": inum, "type": res[0], "size": res[4], "addrs": res[5:]}

    def get_dir_entries(self, inode):
        if inode['type'] != 1: return []
        entries = []
        for addr in inode['addrs'][:12]:
            if addr == 0: continue
            self.f.seek(addr * BSIZE)
            block = self.f.read(BSIZE)
            for i in range(0, BSIZE, 16):
                inum, name = struct.unpack("<H14s", block[i:i+16])
                if inum != 0: entries.append((inum, name.decode().strip('\x00')))
        return entries

    def repair_analysis(self):
        print("\n=== FS REPAIR ANALYSIS REPORT ===")
        allocated = {i: self.get_inode(i) for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()
        broken = []

        def walk(inum, path=""):
            if inum in reachable: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1:
                entries = self.get_dir_entries(ino)
                if not entries and ino['size'] > 0: print(f"[!] Scenario A: Dir {path} (Inum {inum}) corrupted.")
                for cinum, name in entries:
                    if name not in [".", ".."]:
                        if self.get_inode(cinum)['type'] == 0: broken.append((path+"/"+name, cinum))
                        else: walk(cinum, path+"/"+name)

        walk(ROOTINO)
        orphans = set(allocated.keys()) - reachable
        for p, i in broken: print(f"[!] Broken Link: {p} -> Inode {i} (Metadata Missing)")
        for o in orphans: print(f"[!] Orphan: Inode {o} (Type: {allocated[o]['type']}, Size: {allocated[o]['size']})")

if __name__ == "__main__":
    XV6RecoverySuite("fs.img").repair_analysis()
```

