        self.f = open(img, "rb+")
        self.f.seek(BSIZE)
        sb = struct.unpack("<IIIIIIII", self.f.read(32))
        self.ninodes, self.inodestart = sb[3], sb[6]
    def get_inode(self, inum):
        self.f.seek((self.inodestart * BSIZE) + (inum * 64))
        res = struct.unpack("<hhhhI13I", self.f.read(64))
        return {"type": res[0], "addrs": res[5:]}
    def repair(self):
        allocated = {i for i in range(1, self.ninodes) if self.get_inode(i)['type'] != 0}
        reachable = set()
        def walk(inum):
            if inum in reachable or inum == 0: return
            reachable.add(inum)
            ino = self.get_inode(inum)
            if ino['type'] == 1:
                for addr in ino['addrs'][:12]:
                    if addr == 0: continue
                    self.f.seek(addr * BSIZE)
                    block = self.f.read(BSIZE)
                    for i in range(0, BSIZE, 16):
                        c, n = struct.unpack("<H14s", block[i:i+16])
                        if c != 0 and n.strip(b'\x00') not in [b'.', b'..']: walk(c)
        walk(ROOTINO)
        print(f"Orphaned Inodes: {allocated - reachable}")
if __name__ == "__main__":
    r = XV6Recovery("fs.img")
    if "repair" in sys.argv: r.repair()
