### 3. Kernel and Header Modifications (xv6-riscv)

#### A. `kernel/fs.h` additions
```c
struct inode_info {
  uint type;
  short major;
  short minor;
  short nlink;
  uint size;
  uint addrs[13];
};
```

#### B. `kernel/sysfile.c` implementation
```c
#include "fs.h"
#include "buf.h"

uint64 sys_get_dinode(void) {
  int inum;
  uint64 addr; 
  struct buf *bp;
  struct dinode *dip;
  struct superblock sb;

  if(argint(0, &inum) < 0 || argaddr(1, &addr) < 0) return -1;

  bp = bread(1, 1);
  memmove(&sb, bp->data, sizeof(sb));
  brelse(bp);

  if(inum < 0 || inum >= sb.ninodes) return -1;

  bp = bread(1, IBLOCK(inum, sb));
  dip = (struct dinode*)bp->data + (inum % IPB);

  struct inode_info info;
  info.type = dip->type;
  info.nlink = dip->nlink;
  info.size = dip->size;
  memmove(info.addrs, dip->addrs, sizeof(info.addrs));
  brelse(bp);

  if(copyout(myproc()->pagetable, addr, (char *)&info, sizeof(info)) < 0) return -1;
  return 0;
}
```

