#include "kernel/fs.h"
#include "user/user.h"

void walk(char *path) {
  int fd;
  struct dirent de;
  struct stat st;
  char buf[512], *p;
  if((fd = open(path, 0)) < 0) return;
  if(fstat(fd, &st) < 0 || st.type != T_DIR) { close(fd); return; }
  strcpy(buf, path);
  p = buf+strlen(buf);
  if(*(p-1) != '/') *p++ = '/';
  while(read(fd, &de, sizeof(de)) == sizeof(de)){
    if(de.inum == 0 || strcmp(de.name, ".") == 0 || strcmp(de.name, "..") == 0) continue;
    memmove(p, de.name, DIRSIZ);
    p[DIRSIZ] = 0;
    if(stat(buf, &st) < 0) continue;
    printf("Path: %-20s | Inode: %d | Type: %d\n", buf, de.inum, st.type);
    if(st.type == T_DIR) walk(buf);
  }
  close(fd);
}

int main(int argc, char *argv[]) {
  walk(argc > 1 ? argv[1] : "/");
  exit(0);
}
