import java.util.Arrays;

public class SBoxNLAT {

    public static void main(String[] args) {
        // The 3-bit S-box provided in the context
        // (Example: [7, 1, 2, 3, 4, 5, 6, 0]. Replace with your specific values if different.)
        int[] sbox = {7, 1, 2, 3, 4, 5, 6, 0};
        int n = 3;

