        int[][] nlat = calculateNLAT(sbox, n);

        // 2. Output the table
        printTable(nlat);

        // 3. Validation and Test Cases
        validate(nlat, n);
    }

    /**
     * Calculates NLAT entries using the bitwise dot product parity.
     * Formula: NLAT(a, b) = #{x | parity(a & x) == parity(b & S(x))} - 2^(n-1)
     */
    public static int[][] calculateNLAT(int[] sbox, int n) {
        int size = 1 << n;
        int[][] table = new int[size][size];

        for (int a = 0; a < size; a++) {
            for (int b = 0; b < size; b++) {
                int matches = 0;
                for (int x = 0; x < size; x++) {
                    int inputParity = Integer.bitCount(a & x) % 2;
                    int outputParity = Integer.bitCount(b & sbox[x]) % 2;

                    if (inputParity == outputParity) {
                        matches++;
                    }
                }
                // Normalize by subtracting 2^(n-1) to center values at 0
                table[a][b] = matches - (size / 2);
            }
        }
        return table;
    }

