     */
    public static void validate(int[][] nlat, int n) {
        System.out.println("\n--- Validation Report ---");
        int size = 1 << n;
        boolean passed = true;

        // Property 1: NLAT(0,0) must always be 2^(n-1)
        if (nlat[0][0] != (size / 2)) {
