/**
 * Node structure for the Binary Search Tree.
 */
struct Node {
    int data;
    Node* left;
    Node* right;

    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

/**
 * Selection Sort Algorithm: O(n^2)
 * Repeatedly finds the minimum element from the unsorted portion and moves it to the front.
 */
void selectionSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; ++i) {
        int minIdx = i;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[minIdx]) {
                minIdx = j;
            }
        }
        std::swap(arr[i], arr[minIdx]);
    }
}

/**
 * Constructs a balanced BST from a sorted array.
 * Picking the middle element as the root ensures the tree height is O(log n).
 */
Node* sortedArrayToBST(const std::vector<int>& arr, int start, int end) {
    if (start > end) return nullptr;

    int mid = start + (end - start) / 2;
    Node* root = new Node(arr[mid]);

    root->left = sortedArrayToBST(arr, start, mid - 1);
    root->right = sortedArrayToBST(arr, mid + 1, end);

    return root;
}

/**
 * In-order traversal to print the tree and verify it is a valid BST.
 */
void printInOrder(Node* root) {
    if (!root) return;
    printInOrder(root->left);
    std::cout << root->data << " ";
    printInOrder(root->right);
}

