struct Node {
    int data;
    Node* left;
    Node* right;

    Node(int val) : data(val), left(nullptr), right(nullptr) {}
};

/**
 * Selection Sort Algorithm: O(n^2)
 * Repeatedly finds the minimum element from the unsorted part and swaps it to the front.
 */
void selectionSort(std::vector<int>& arr) {
    int n = arr.size();
    for (int i = 0; i < n - 1; ++i) {
        int min_idx = i;
        for (int j = i + 1; j < n; ++j) {
            if (arr[j] < arr[min_idx]) {
                min_idx = j;
            }
        }
        // Swap the found minimum element with the first element of the unsorted portion
        std::swap(arr[i], arr[min_idx]);
    }
}

/**
 * Function to construct a balanced BST from a sorted array.
 * This ensures O(log n) height for optimal performance.
 */
Node* buildBalancedBST(const std::vector<int>& arr, int start, int end) {
    if (start > end) {
        return nullptr;
    }

    // Middle element becomes the root to maintain balance
    int mid = start + (end - start) / 2;
    Node* root = new Node(arr[mid]);

    // Recursively construct left and right subtrees
    root->left = buildBalancedBST(arr, start, mid - 1);
    root->right = buildBalancedBST(arr, mid + 1, end);

    return root;
}

/**
 * In-order traversal (Left, Root, Right) to verify the tree structure.
 */
void inOrder(Node* root) {
    if (root == nullptr) return;
    inOrder(root->left);
    std::cout << root->data << " ";
    inOrder(root->right);
