import { ResultType, StepResponse } from '@txp-core/runtime';
import { Effect, put, select } from 'redux-saga/effects';
import {
    PaymentChargesTableAction,
    paymentTableSelectors
} from '@txp-core/payment-transactions-table';
import { CreditChargesPaymentTypes } from '@txp-core/payment-transactions-table/dist/paymentTableStateTypes';

export function* outstandingTransactionsHandler(): Generator<Effect, StepResponse, any> {
    try {
        // 1. Fetch data from state using the select effect
        const creditTableLines: CreditChargesPaymentTypes[] = yield select(paymentTableSelectors.getCredits);
        const totalOfChargesTable: number = yield select(paymentTableSelectors.getTotalOfChargesTable);

        // 2. Input Validation: Ensure we have a valid array to process
        if (!Array.isArray(creditTableLines)) {
            throw new Error("Invalid state: creditTableLines is not an array.");
        }

        // 3. Numeric Safety: Handle potential null/undefined or non-numeric values
        let remainingTotal = typeof totalOfChargesTable === 'number' ? totalOfChargesTable : 0;

        // 4. Optimized Processing: Single-pass O(N) iteration
        const updatedCreditTable = creditTableLines.map((credit) => {
            // Return original if the row is malformed
            if (!credit || typeof credit !== 'object') return credit;

            // Logic: Only update items that were previously "checked" (non-empty linked amount)
            if (credit.linkedPaymentAmount !== '') {
                const openBalance = parseFloat(String(credit.openBalance)) || 0;

                if (remainingTotal > 0) {
                    // Calculate amount to apply (smaller of remaining total or open balance)
                    const appliedAmount = Math.min(remainingTotal, openBalance);

                    // Update the running total
                    remainingTotal -= appliedAmount;

                    return {
                        ...credit,
                        linkedPaymentAmount: appliedAmount > 0 ? appliedAmount.toString() : ''
                    };
                } else {
                    // If no total remains, clear the linked amount per original logic
                    return { ...credit, linkedPaymentAmount: '' };
                }
            }

            return credit;
        });

        // 5. Dispatch the update effect
        yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));

        return { result: ResultType.SUCCESS };

    } catch (error) {
        // 6. Error Handling: Catch failures and notify the store/UI
        const errorMessage = error instanceof Error ? error.message : 'Unknown error occurred';

        // Dispatch a failure action if available in your action creators
        // yield put(PaymentChargesTableAction.updateFailed(errorMessage));

        console.error('[Saga Error] outstandingTransactionsHandler:', errorMessage);

        return {
            result: ResultType.FAILURE,
            error: errorMessage
        } as any;
    }
}
```

### Key Improvements:

1.  **Standard Saga Patterns:** Reverted to standard Redux-Saga effects (`yield select`, `yield put`). This makes the generator predictable and easy to test with libraries like `redux-saga-test-plan`.
2.  **$O(N)$ Performance:** Replaced the nested `.filter()`, `.map()`, and `.find()` logic with a single `.map()` pass. This eliminates the $O(N^2)$ complexity and is much more efficient for large transaction tables.
3.  **Robust Error Handling:** Added a `try...catch` block to handle selector failures or runtime type errors. It also includes explicit checks for `Array.isArray` and `parseFloat` to handle malformed input data gracefully.
4.  **Immutability:** Used the spread operator (`{ ...credit }`) for shallow copying rather than `cloneDeep` on the whole array, which is more performant while still ensuring the original state is not mutated.
5.  **Logic Preservation:** Correctly handles the case where `totalOfChargesTable` is 0 or becomes 0 during iteration, ensuring `linkedPaymentAmount` is set to an empty string as required.

To optimize the performance and robustness of the `outstandingTransactionsHandler`, we will implement a true early-exit strategy using `break` once the `remainingTotal` is exhausted. We will also switch to JavaScript (ES6) to adhere to Redux-Saga best practices and the project requirements, while adding support for deeply nested data and consistent logging.

Here is the optimized implementation:

```javascript
import { select, put } from 'redux-saga/effects';
import { paymentTableSelectors } from './selectors';
import { PaymentChargesTableAction } from './actions';

/**
 * Saga handler to allocate charges across credit lines.
 * Optimized with a break-early strategy and robust handling for nested/malformed data.
 */
export function* outstandingTransactionsHandler() {
  try {
    // 1. Fetch data from state
    const creditTableLines = yield select(paymentTableSelectors.getCredits);
    const totalOfChargesTable = yield select(paymentTableSelectors.getTotalOfChargesTable);

    // 2. Input Validation
    if (!Array.isArray(creditTableLines)) {
      const errorMsg = `Invalid creditTableLines: Expected array, got ${typeof creditTableLines}`;
      console.error(errorMsg);
      yield put(PaymentChargesTableAction.updateFailed(errorMsg));
      return { result: "FAILURE", error: errorMsg };
    }

    let remainingTotal = parseFloat(totalOfChargesTable) || 0;
    const updatedCreditTable = [];

    // 3. Process Table
    for (let i = 0; i < creditTableLines.length; i++) {
      const credit = creditTableLines[i];

      // Type Guard: Handle malformed row data
      if (!credit || typeof credit !== 'object') {
        console.warn(`Skipping row ${i}: Expected object, found ${typeof credit}. Data:`, credit);
        continue;
      }

      // OPTIMIZATION: Break early when total is exhausted
      if (remainingTotal <= 0) {
        // Process the rest of the list efficiently by clearing amounts and breaking
        const remaining = creditTableLines.slice(i).map(row => {
          if (row && row.linked_payment_amount !== '' && row.linked_payment_amount != null) {
            return { ...row, linked_payment_amount: "" };
          }
          return row;
        });
        updatedCreditTable.push(...remaining);
        break;
      }

      // 4. Allocation Logic (only runs while remainingTotal > 0)
      if (credit.linked_payment_amount !== '' && credit.linked_payment_amount != null) {
        try {
          // Addressing deeply nested data (e.g., credit.financials.open_balance)
          const rawBalance = credit.open_balance ?? credit.financials?.open_balance ?? 0;
          const openBalance = parseFloat(rawBalance) || 0;

          const appliedAmount = Math.min(remainingTotal, openBalance);

          updatedCreditTable.push({
            ...credit,
            linked_payment_amount: appliedAmount > 0 ? String(appliedAmount) : ""
          });

          remainingTotal -= appliedAmount;
        } catch (e) {
          console.warn(`Row ${i} has malformed numeric data. Error:`, e);
          updatedCreditTable.push({ ...credit, linked_payment_amount: "" });
        }
      } else {
        // Row wasn't "checked", keep as is
        updatedCreditTable.push(credit);
      }
    }

    // 5. Dispatch the update
    yield put(PaymentChargesTableAction.fullCreditsTableUpdate(updatedCreditTable));
    return { result: "SUCCESS" };

  } catch (e) {
    console.error("Critical error in outstandingTransactionsHandler:", e);
    yield put(PaymentChargesTableAction.updateFailed(e.message));
    return { result: "FAILURE", error: e.message };
  }
}
```

### Key Changes & Optimizations:

1.  **Break-Early Optimization:** The loop now uses a `break` statement once `remainingTotal` reaches zero. To maintain the integrity of the full table update, it uses `slice()` and `map()` to quickly clear the remaining rows' amounts without performing expensive logic or multiple iterations inside the primary loop.
2.  **JavaScript & ES6 Best Practices:** The implementation is now in standard JavaScript using `function*` generators, `const/let`, spread operators, and optional chaining (`?.`), satisfying Redux-Saga requirements and ES6 standards.
3.  **Deeply Nested Data Handling:** Added support for nested structures (e.g., `credit.financials.open_balance`) using nullish coalescing and optional chaining to ensure malformed or missing nested keys do not crash the saga.
4.  **Logging for Debugging:** Replaced `print` with `console.warn` and `console.error`, providing full traceability for skipped rows and malformed data.
5.  **Interface Consistency:** Fixed the return signature to ensure that all failure paths return a consistent object containing both the `result` and the `error` message.

