```python
"use client";

import React, { useState, useEffect } from 'react';
import { db } from "@/lib/firebase";
import { 
  collection, 
  addDoc, 
  doc, 
  updateDoc, 
  onSnapshot, 
  query, 
  orderBy,
  serverTimestamp 
} from "firebase/firestore";

// MarkdownRX components for professional editing and rendering
import { MarkdownEditor, MarkdownRenderer } from 'markdownrx'; 

/**
 * DocumentationSystem
 * A comprehensive component for managing, editing, and viewing documentation.
 * Emphasizes clean UI, professional markdown formatting, and file management.
 */
export default function DocumentationSystem() {
  const [documents, setDocuments] = useState([]);
  const [activeDoc, setActiveDoc] = useState(null);
  const [isEditing, setIsEditing] = useState(false);
  const [loading, setLoading] = useState(true);
  const [editContent, setEditContent] = useState("");

  // 1. Sync with Firebase Firestore
  useEffect(() => {
    // Using "documentation" collection as established in the initial setup
    const q = query(collection(db, "documentation"), orderBy("createdAt", "desc"));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const docsData = snapshot.docs.map(d => ({
        id: d.id,
        ...d.data()
      }));
      setDocuments(docsData);

      if (docsData.length > 0 && !activeDoc) {
        setActiveDoc(docsData[0]);
        setEditContent(docsData[0].content);
      }
      setLoading(false);
    }, (error) => {
      console.error("Firebase Sync Error: Check your @/lib/firebase setup.", error);
      setLoading(false);
    });

    return () => unsubscribe();
  }, [activeDoc]);

  // 2. Save changes to Firestore
  const handleSave = async () => {
    if (!activeDoc) return;
    try {
      const docRef = doc(db, "documentation", activeDoc.id);
      await updateDoc(docRef, {
        content: editContent,
        updatedAt: serverTimestamp(),
      });
      setIsEditing(false);
      setActiveDoc({ ...activeDoc, content: editContent });
    } catch (error) {
      alert("Failed to save document. Check your Firestore permissions.");
    }
  };

  // 3. Create new documentation page
  const handleCreateNew = async () => {
    const title = prompt("Enter the title for the new documentation page:");
    if (!title) return;

    const newDoc = {
      title,
      content: `# ${title}\n\nStart typing your documentation here...`,
      createdAt: serverTimestamp(),
    };

    const docRef = await addDoc(collection(db, "documentation"), newDoc);
    setActiveDoc({ id: docRef.id, ...newDoc });
    setEditContent(newDoc.content);
    setIsEditing(true);
  };

  // 4. Handle Markdown File Upload
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      const content = event.target.result;
      const newDoc = {
        title: file.name.replace(".md", ""),
        content: content,
        createdAt: serverTimestamp(),
      };

      const docRef = await addDoc(collection(db, "documentation"), newDoc);
      setActiveDoc({ id: docRef.id, ...newDoc });
      setEditContent(content);
      setIsEditing(false);
    };
    reader.readAsText(file);
  };

  if (loading) return (
    <div className="flex items-center justify-center h-screen bg-gray-50">
      <div className="animate-pulse text-gray-500 font-medium">Initializing Documentation System...</div>
    </div>
  );

  return (
    <div className="flex h-screen bg-white text-slate-900">
      {/* Sidebar Navigation */}
      <aside className="w-72 border-r border-slate-200 bg-slate-50 flex flex-col">
        <div className="p-6 border-b border-slate-200 flex justify-between items-center">
          <h2 className="font-bold text-slate-800 tracking-tight">Documentation</h2>
          <button 
            onClick={handleCreateNew}
            className="p-1.5 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition shadow-sm"
            title="New Page"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
            </svg>
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto p-4 space-y-1">
          {documents.map((doc) => (
            <button
              key={doc.id}
              onClick={() => { 
                setActiveDoc(doc); 
                setEditContent(doc.content);
                setIsEditing(false); 
              }}
              className={`w-full text-left px-4 py-2.5 rounded-lg text-sm transition-all ${
                activeDoc?.id === doc.id 
                ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-slate-200 font-semibold' 
                : 'text-slate-600 hover:bg-slate-200'
              }`}
            >
              {doc.title}
            </button>
          ))}
        </nav>

        {/* File Upload Footer */}
        <div className="p-6 border-t border-slate-200 bg-slate-100/50">
          <label className="block text-xs font-bold text-slate-500 uppercase mb-3 tracking-wider">
            Upload .md File
          </label>
          <input 
            type="file" 
            accept=".md" 
            onChange={handleFileUpload} 
            className="block w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-md file:border-0 file:text-xs file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 cursor-pointer"
          />
        </div>
      </aside>

      {/* Main Content Area */}
      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {activeDoc ? (
          <>
            <header className="h-16 border-b border-slate-200 px-8 flex justify-between items-center bg-white">
              <div className="flex items-center space-x-4">
                <span className="text-slate-400 text-sm">Pages /</span>
                <h1 className="font-semibold text-slate-800 truncate">{activeDoc.title}</h1>
              </div>
              <div className="flex items-center space-x-3">
                {isEditing ? (
                  <>
                    <button 
                      onClick={() => setIsEditing(false)}
                      className="px-4 py-1.5 text-sm font-medium text-slate-600 hover:text-slate-800"
                    >
                      Cancel
                    </button>
                    <button 
                      onClick={handleSave}
                      className="px-4 py-1.5 text-sm font-medium bg-indigo-600 text-white rounded-md hover:bg-indigo-700 shadow-sm"
                    >
                      Save Changes
                    </button>
                  </>
                ) : (
                  <button 
                    onClick={() => setIsEditing(true)}
                    className="px-4 py-1.5 text-sm font-medium border border-slate-300 rounded-md hover:bg-slate-50 transition"
                  >
                    Edit Page
                  </button>
                )}
              </div>
            </header>

            <div className="flex-1 overflow-y-auto bg-white">
              <div className="max-w-4xl mx-auto py-12 px-8">
                {isEditing ? (
                  <div className="border rounded-xl shadow-inner bg-slate-50 overflow-hidden">
                    <MarkdownEditor
                      value={editContent}
                      onChange={(val) => setEditContent(val)}
                      minHeight="500px"
                      className="w-full p-4 focus:outline-none"
                    />
                  </div>
                ) : (
                  <article className="prose prose-slate prose-indigo max-w-none">
                    <MarkdownRenderer content={activeDoc.content} />
                  </article>
                )}
              </div>
            </div>
          </>
        ) : (
          <div className="flex flex-col items-center justify-center h-full text-slate-400">
            <p>Select a document from the sidebar or create a new one.</p>
          </div>
        )}
      </main>
    </div>
  );
}
```

### Key Features of this Implementation:

*   **Formatting Alignment**: By using the `prose` class from Tailwind Typography in the `MarkdownRenderer` container, the documentation automatically receives professional styling for headers, lists, and code blocks.
*   **Flexible Ingestion**: Supports both manual page creation and **Markdown File Uploading**, allowing you to import existing documentation directly into your Firebase-backed system.
*   **State Management**: Editing uses a local state buffer (`editContent`) to ensure that changes are only persisted to Firestore when the user explicitly saves, preventing unnecessary writes.
*   **Modern UI**: The interface utilizes a clean, SaaS-style sidebar with subtle transitions and professional Indigo accents, built entirely with Tailwind CSS utilities.

