#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <iomanip>
#include <typeinfo>

// --- 1. BASE CLASS & ENCAPSULATION ---
class Exhibit {
protected:
    std::string name;
    int year;

public:
    Exhibit(std::string n, int y) : name(n), year(y) {}
    virtual ~Exhibit() = default;

    // 5. Polymorphism: Virtual method
    virtual void display() const = 0;

    std::string getName() const { return name; }
    int getYear() const { return year; }

    // 6. Operator Overloading: Combine names of two exhibits
    std::string operator+(const Exhibit& other) const {
        return "Collection: " + this->name + " & " + other.name;
    }
};

// --- 2. DERIVED CLASSES & INHERITANCE ---
class Painting : public Exhibit {
private:
    std::string artist;
public:
    Painting(std::string n, int y, std::string a) : Exhibit(n, y), artist(a) {}
    void display() const override {
        std::cout << "[Painting] '" << name << "' by " << artist << " (" << year << ")" << std::endl;
    }
};

class Sculpture : public Exhibit {
private:
    std::string material;
public:
    Sculpture(std::string n, int y, std::string m) : Exhibit(n, y), material(m) {}
    void display() const override {
        std::cout << "[Sculpture] '" << name << "' made of " << material << " (" << year << ")" << std::endl;
    }
};

class HistoricalArtifact : public Exhibit {
private:
    std::string origin;
public:
    HistoricalArtifact(std::string n, int y, std::string o) : Exhibit(n, y), origin(o) {}
    void display() const override {
        std::cout << "[Artifact] '" << name << "' from " << origin << " (" << year << ")" << std::endl;
    }
};

// --- 5. TEMPLATE CLASS & 8. STL LIBRARY ---
template <typename T>
class MuseumCollection {
private:
    // STL vector for dynamic storage
    std::vector<std::unique_ptr<T>> items;

public:
    // 6. Method Overloading: Handles unique_ptr or raw pointers
    void addExhibit(std::unique_ptr<T> item) {
        items.push_back(std::move(item));
    }

    void addExhibit(T* item) {
        items.emplace_back(item);
    }

    // 1. Data Analysis and Processing
    void performAnalysis() const {
        if (items.empty()) {
            std::cout << "Collection is empty." << std::endl;
            return;
        }

        int currentYear = 2024;
        double totalAge = 0;
        // STL map for data aggregation
        std::map<std::string, int> typeCounts;

        for (const auto& item : items) {
            totalAge += (currentYear - item->getYear());
            // Use typeid for a simple type breakdown report
            typeCounts[typeid(*item).name()]++;
        }

        std::cout << "\n--- Data Analysis Report ---" << std::endl;
        std::cout << "Total Exhibits: " << items.size() << std::endl;
        std::cout << "Average Age: " << std::fixed << std::setprecision(1) << (totalAge / items.size()) << " years" << std::endl;
        std::cout << "Breakdown by Type:" << std::endl;
        for (auto const& [type, count] : typeCounts) {
            std::cout << " - " << type << ": " << count << std::endl;
        }
        std::cout << "----------------------------" << std::endl;
    }

    void showAll() const {
        for (const auto& item : items) {
            item->display();
        }
    }
};

int main() {
    MuseumCollection<Exhibit> museum;

    // Populate collection using overloaded methods
    museum.addExhibit(std::make_unique<Painting>("The Starry Night", 1889, "Vincent van Gogh"));
    museum.addExhibit(std::make_unique<Sculpture>("David", 1504, "Marble"));
    museum.addExhibit(new HistoricalArtifact("Rosetta Stone", -196, "Egypt"));

    std::cout << "Museum Exhibits:" << std::endl;
    museum.showAll();

    // Perform and show data analysis
    museum.performAnalysis();

    // Demonstrate operator overloading
    Painting p1("Mona Lisa", 1503, "Leonardo da Vinci");
    Painting p2("The Night Watch", 1642, "Rembrandt");
    std::cout << "\nOperator Overloading Result: " << (p1 + p2) << std::endl;

    return 0;
}
```

