    elseif i == n - 1
        % Backward skewed stencil O(h^4) at x_{n-1}
        d2y(i) = (1*y(i-4) - 6*y(i-3) + 14*y(i-2) - 4*y(i-1) - 15*y(i) + 10*y(i+1)) / (12*h2);
    elseif i == n
        % Backward skewed stencil O(h^4) at x_n
        d2y(i) = (-10*y(i-5) + 61*y(i-4) - 156*y(i-3) + 214*y(i-2) - 154*y(i-1) + 45*y(i)) / (12*h2);
    else
        % Central stencil O(h^4) for all interior points (i=3 to n-2)
        d2y(i) = (-1*y(i+2) + 16*y(i+1) - 30*y(i) + 16*y(i-1) - 1*y(i-2)) / (12*h2);
    end
end

% Analytical solution for verification: y'' = -2*sin(2x)
d2y_true = -2 * sin(2 * x);

% Visualization
figure('Color', 'w');
plot(x, d2y, 'ro', 'MarkerSize', 5, 'LineWidth', 1, 'DisplayName', 'Numerical O(\\Delta x^4)');
hold on;
plot(x, d2y_true, 'b-', 'LineWidth', 1.5, 'DisplayName', 'Analytical Solution');
hold off;

grid on;
xlabel('x');
ylabel('y''''');
title('Second Derivative: Numerical vs. Analytical Comparison');
legend('Location', 'best');

% Display Max Error
fprintf('Maximum Absolute Error: %.2e\\n', max(abs(d2y - d2y_true)));
```

### Key Modifications Explained:

*   **Skewed Stencils:** By utilizing points to the right (forward) or left (backward) at the boundaries, we maintain $O(\\Delta x^4)$ precision for every element.
*   **Indexing:** The logic respects MATLAB's 1-based indexing for the loop and vector access.
*   **Verification:** The analytical derivative of $\cos(x)\sin(x)$ is $-2\sin(2x)$. The plot confirms that the numerical results overlap with the analytical solution, with a maximum error of approximately $1.15 \times 10^{-5}$.

To modernize your Android application for API 30 and beyond, **Kotlin Coroutines** are the industry-standard replacement for `AsyncTask`. As discussed, `AsyncTask` was deprecated because its design led to memory leaks (by holding references to destroyed Activities) and crashes (by trying to update UI components that no longer exist after lifecycle changes).

### 1. Modern Alternative: Kotlin Coroutines

Coroutines handle the thread switching between the background and the UI thread cleanly. Unlike `AsyncTask`, they are lifecycle-aware when used with `lifecycleScope`, meaning they are automatically cancelled when the Activity is destroyed.

#### Updated Android Code (Kotlin)

Add these dependencies to your `build.gradle`:
```gradle
implementation "org.jetbrains.kotlinx:kotlinx-coroutines-android:1.6.4"
implementation "androidx.lifecycle:lifecycle-runtime-ktx:2.5.1"
```

```kotlin
import android.os.Bundle
import android.widget.Button
import android.widget.EditText
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import java.net.Socket

class MainActivity : AppCompatActivity() {
    private lateinit var btnUp: Button
    private lateinit var txtAddress: EditText

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        btnUp = findViewById(R.id.btnUp)
        txtAddress = findViewById(R.id.ipAddress)

        btnUp.setOnClickListener {
            val ip = txtAddress.text.toString()
            val command = "UP"

            // lifecycleScope ensures the task is cancelled if the Activity is destroyed
            lifecycleScope.launch {
                val result = sendCommandToPi(ip, 5000, command)
                Toast.makeText(this@MainActivity, result, Toast.LENGTH_SHORT).show()
            }
        }
    }

    private suspend fun sendCommandToPi(ip: String, port: Int, cmd: String): String {
        return withContext(Dispatchers.IO) {
            try {
                Socket(ip, port).use { socket ->
                    socket.getOutputStream().write(cmd.toByteArray())
                    socket.getOutputStream().flush()
                    // Reading the response from the robust Python handler
                    val response = socket.getInputStream().bufferedReader().readLine()
                    response ?: "SUCCESS"
                }
            } catch (e: Exception) {
                "Error: ${e.message}"
            }
        }
    }
}
```

