### 3. Python Implementation: Multi-Threaded Robust Server

To maintain the robust structure established previously while handling concurrent requests from Coroutines, we use a multi-threaded approach. This version preserves the correct script paths and argument structure from our previous configuration.

```python
import socket
import threading
import subprocess
import logging

logging.basicConfig(level=logging.INFO, format='%(threadName)s: %(message)s')

class PiCommandHandler:
    def __init__(self):
        # Preserving the established paths and arguments from Turn 4
        self.command_registry = {
            "UP": ["/usr/bin/python3", "/home/pi/scripts/motor.py", "forward"],
            "DOWN": ["/usr/bin/python3", "/home/pi/scripts/motor.py", "backward"],
            "STOP": ["/usr/bin/python3", "/home/pi/scripts/motor.py", "stop"]
        }

    def process_request(self, raw_data):
        command_key = raw_data.decode('utf-8').strip().upper()
        if command_key in self.command_registry:
            logging.info(f"Executing: {command_key}")
            return self._execute_shell_command(self.command_registry[command_key])
        return "ERROR: INVALID_COMMAND"

    def _execute_shell_command(self, cmd_list):
        try:
            # capture_output ensures we can report success/failure back to Android
            result = subprocess.run(cmd_list, capture_output=True, text=True, check=True)
            return f"SUCCESS: {result.stdout.strip()}"
        except subprocess.CalledProcessError as e:
            return f"ERROR: {e.returncode}"

def handle_client(conn, addr, handler):
    try:
        with conn:
            data = conn.recv(1024)
            if data:
                response = handler.process_request(data)
                conn.sendall((response + "\n").encode('utf-8'))
    except Exception as e:
        logging.error(f"Connection error with {addr}: {e}")

def start_server(host='0.0.0.0', port=5000):
    handler = PiCommandHandler()
    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        s.bind((host, port))
        s.listen()
        logging.info(f"Threaded Server listening on {port}...")
        while True:
            conn, addr = s.accept()
            threading.Thread(target=handle_client, args=(conn, addr, handler)).start()

if __name__ == "__main__":
    start_server()
```

