fprintf('Analytical Cl (Cylinder): %.4f\n', cl_analytical);
fprintf('Cl Absolute Error: %.4e\n', abs(cl - cl_analytical));

% Analytical Cp Comparison (Cylinder Case)
theta_analytical = linspace(0, 2*pi, 200);
cp_analytical = 1 - 4*(sin(theta_analytical - alpha)).^2;

% Plotting Results
