grid on;
xlabel('x-coordinate');
ylabel('C_p');
title(['Pressure Coefficient Distribution (C_l = ', num2str(cl, '%.4f'), ')']);
legend show;

%% --- Solver Function ---
function [xc, cp, cl] = solve_panel_method(x, y, V_inf, alpha)
    num_pts = length(x);
    num_panels = num_pts - 1;

    xc = zeros(num_panels, 1);
    yc = zeros(num_panels, 1);
    S = zeros(num_panels, 1);
    phi = zeros(num_panels, 1);
    beta = zeros(num_panels, 1);

    for i = 1:num_panels
        xc(i) = (x(i) + x(i+1)) / 2;
        yc(i) = (y(i) + y(i+1)) / 2;
        dx = x(i+1) - x(i);
        dy = y(i+1) - y(i);
        S(i) = sqrt(dx^2 + dy^2);
        phi(i) = atan2(dy, dx);
        beta(i) = phi(i) + pi/2 - alpha;
    end

    A = zeros(num_panels + 1, num_panels + 1);
    B = zeros(num_panels, num_panels);

    for i = 1:num_panels
        for j = 1:num_panels
            if i == j
                A(i, j) = 0.5;
                B(i, j) = 0;
            else
                dx = xc(i) - x(j);
                dy = yc(i) - y(j);
                x_loc = dx * cos(phi(j)) + dy * sin(phi(j));
                y_loc = -dx * sin(phi(j)) + dy * cos(phi(j));

                r1 = x_loc^2 + y_loc^2;
                r2 = (x_loc - S(j))^2 + y_loc^2;
                th1 = atan2(y_loc, x_loc);
                th2 = atan2(y_loc, x_loc - S(j));

                f_src_n = 0.5/(2*pi) * log(r1/r2);
                f_src_t = (th2 - th1)/(2*pi);

                A(i, j) = f_src_n * cos(phi(i)-phi(j)) + f_src_t * sin(phi(i)-phi(j));
                B(i, j) = -f_src_n * sin(phi(i)-phi(j)) + f_src_t * cos(phi(i)-phi(j));
            end
        end
        A(i, end) = -sum(B(i, 1:num_panels));
    end

    A(end, 1) = 1;
    A(end, num_panels) = 1;
    A(end, end) = 0;

    rhs = -V_inf * cos(beta);
    rhs(end + 1) = 0;

    res = A \ rhs';
    lambdas = res(1:end-1);
    gamma = res(end);

    Vt = zeros(num_panels, 1);
    for i = 1:num_panels
        term1 = V_inf * sin(beta(i));
        term2 = sum(lambdas .* B(i, :)');
        term3 = gamma * sum(A(i, 1:num_panels));
        Vt(i) = term1 + term2 + term3;
    end

    cp = 1 - (Vt ./ V_inf).^2;
    chord = max(x) - min(x);
    total_gamma = gamma * sum(S);
    cl = (2 * total_gamma) / (V_inf * chord);
end
```

