```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <memory>
#include <stdexcept>
#include <algorithm>

class IzhikevichNeuron;

/**
 * @brief Represents a synaptic connection with Spike-Timing-Dependent Plasticity (STDP).
 */
struct Synapse {
    IzhikevichNeuron* target;
    double weight;
    double last_pre_spike = -1000.0;
    const double tau_stdp = 20.0;
    const double learning_rate = 0.01;

    Synapse(IzhikevichNeuron* t, double w) : target(t), weight(w) {}

    void update_weight(double t, bool is_pre_spike, double other_spike_time) {
        // Calculate time difference between pre and post spikes
        double dt = is_pre_spike ? (t - other_spike_time) : (t - last_pre_spike);

        if (is_pre_spike) {
            last_pre_spike = t;
            // LTD: Pre-synaptic spike occurs after a post-synaptic spike
            if (dt > 0) weight -= learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        } else {
            // LTP: Post-synaptic spike occurs after a pre-synaptic spike
            if (dt > 0) weight += learning_rate * std::exp(-std::abs(dt) / tau_stdp);
        }

        // Maintain biological weight bounds
        if (weight < 0.0) weight = 0.0;
        if (weight > 2.0) weight = 2.0;
    }
};

/**
 * @brief Izhikevich Neuron class for simulating primitive nervous systems.
 */
class IzhikevichNeuron {
private:
    // Model parameters (a, b, c, d)
    double a, b, c, d;
    double v, u; // State variables: membrane potential and recovery
    double current_input = 0.0;
    double last_spike_time = -1000.0;

    // Connections
    std::unordered_map<IzhikevichNeuron*, std::unique_ptr<Synapse>> outbound_synapses;
    std::vector<Synapse*> inbound_synapses; // Weak references for post-synaptic STDP updates

public:
    IzhikevichNeuron(double a = 0.02, double b = 0.2, double c = -65.0, double d = 8.0)
        : a(a), b(b), c(c), d(d), v(-65.0), u(b * -65.0) {}

    /**
     * @brief Dynamically connect to another neuron.
     */
    void connect_to(IzhikevichNeuron* target, double weight = 0.5) {
        if (!target) throw std::invalid_argument("Target neuron cannot be null.");
        if (outbound_synapses.find(target) == outbound_synapses.end()) {
            auto syn = std::make_unique<Synapse>(target, weight);
            target->inbound_synapses.push_back(syn.get());
            outbound_synapses[target] = std::move(syn);
        }
    }

    /**
     * @brief Dynamically disconnect from a neuron.
     */
    void disconnect_from(IzhikevichNeuron* target) {
        if (outbound_synapses.count(target)) {
            Synapse* syn_ptr = outbound_synapses[target].get();
            auto& in = target->inbound_synapses;
            in.erase(std::remove(in.begin(), in.end(), syn_ptr), in.end());
            outbound_synapses.erase(target);
        }
    }

    void receive_input(double current) { current_input += current; }

    /**
     * @brief Step the simulation using Euler integration.
     */
    bool step(double t, double dt = 1.0) {
        bool fired = false;

        // Izhikevich differential equations
        // v' = 0.04v^2 + 5v + 140 - u + I
        // u' = a(bv - u)
        v += dt * (0.04 * v * v + 5.0 * v + 140.0 - u + current_input);
        u += dt * (a * (b * v - u));

        current_input = 0.0; // Reset input for next step

        if (v >= 30.0) {
            fired = true;
            v = c;
            u += d;
            last_spike_time = t;

            // Propagate spike and update STDP (Pre-synaptic side)
            for (auto& pair : outbound_synapses) {
                pair.second->update_weight(t, true, pair.first->last_spike_time);
                pair.first->receive_input(pair.second->weight * 15.0); // Scaling factor
            }
            // Notify for STDP (Post-synaptic side)
            for (auto* synapse : inbound_synapses) {
                synapse->update_weight(t, false, 0); 
            }
        }
        return fired;
    }

    double get_membrane_potential() const { return v; }
    double get_last_spike_time() const { return last_spike_time; }
};

/**
 * @brief Sample code to build and simulate a simple network.
 */
void run_simulation() {
    // Initialize two Regular Spiking neurons
    IzhikevichNeuron n1(0.02, 0.2, -65.0, 8.0);
    IzhikevichNeuron n2(0.02, 0.2, -65.0, 8.0);

    // Dynamic connection
    try {
        n1.connect_to(&n2, 0.5);
        std::cout << "Network initialized. Simulating 100ms..." << std::endl;

        for (int t = 0; t < 100; ++t) {
            n1.receive_input(10.0); // Stimulate the first neuron

            if (n1.step(static_cast<double>(t))) {
                std::cout << "Time " << t << ": Neuron 1 fired!" << std::endl;
            }
            if (n2.step(static_cast<double>(t))) {
                std::cout << "Time " << t << ": Neuron 2 fired!" << std::endl;
            }
        }

        // Dynamic disconnection
        n1.disconnect_from(&n2);
        std::cout << "Simulation complete." << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Simulation Error: " << e.what() << std::endl;
    }
}

int main() {
    run_simulation();
    return 0;
}
```

